import { inkStories } from "./stories/inkStories";

export type FlowNodeType = "start" | "choice" | "event" | "ending" | "death" | "continue" | "story";

export interface FlowNode {
	id: string;
	type: FlowNodeType;
	title: string;
	description?: string;
	choices?: FlowChoice[];
	next?: string;
	endingKind?: "canon" | "if";
	deathReason?: string;
}

export interface FlowChoice {
	text: string;
	target: string;
	isCorrect?: boolean;
}

export interface FlowData {
	storyKey: string;
	title: string;
	chapters: FlowNode[];
}

